<?php account_page_start('Wishlist','wishlist','SAVED PRODUCTS','My wishlist','','Keep the products you might want later.',$user);require_once __DIR__.'/../../includes/store_helpers.php'; ?>
<?php if($message):?><div class="app-alert success"><?=store_h(store_public_message_t($message))?></div><?php endif;?><?php if($error):?><div class="app-alert danger"><?=store_h(store_public_message_t($error))?></div><?php endif;?>
<section class="app-panel dashboard-card tool-card account-wishlist-shell">
  <div class="tool-heading"><div><p class="card-kicker">SAVED PRODUCTS</p><h2><?=count($products)?> <?=store_h(store_t('saved'))?></h2><p class="account-section-copy"><?=store_h(store_t('Everything you saved, all in one place.'))?></p></div><a class="app-button secondary" href="<?=htmlspecialchars(route_url('perfumes.php'),ENT_QUOTES,'UTF-8')?>"><?=store_h(store_t('DISCOVER MORE'))?></a></div>
  <?php if(!$products):?>
    <div class="account-empty-state"><strong><?=store_h(store_t('No saved products yet.'))?></strong><p><?=store_h(store_t('Browse the catalog and save anything you want to revisit.'))?></p><a class="app-button primary" href="<?=htmlspecialchars(route_url('perfumes.php'),ENT_QUOTES,'UTF-8')?>"><?=store_h(store_t('BROWSE PRODUCTS'))?></a></div>
  <?php else:?><div class="account-wishlist-grid">
    <?php foreach($products as $p):$image=store_image_path($p['main_image_path']??'');$stock=(int)($p['available_stock']??0);$regular=(float)($p['regular_price']??0);$price=(float)($p['price']??0);$sale=$regular>0&&$price>0&&$price<$regular; ?>
      <article class="account-wishlist-card">
        <a class="account-wishlist-image" href="<?=htmlspecialchars(store_product_url($p),ENT_QUOTES,'UTF-8')?>"><?php if($image!==''):?><img data-store-image-fallback-source src="<?=htmlspecialchars(url(store_image_variant_path($image,'sm')),ENT_QUOTES,'UTF-8')?>" srcset="<?=htmlspecialchars(store_image_srcset($image),ENT_QUOTES,'UTF-8')?>" sizes="(max-width:700px) 44vw, 260px" loading="lazy" decoding="async" alt="<?=htmlspecialchars((string)$p['name'],ENT_QUOTES,'UTF-8')?>"><span class="account-wishlist-image-fallback" data-store-image-fallback hidden><?=store_h(store_t('IMAGE COMING SOON'))?></span><?php else:?><span class="account-wishlist-image-fallback"><?=store_h(store_t('IMAGE COMING SOON'))?></span><?php endif;?><?php if($sale):?><em><?=store_h(store_t('SALE'))?></em><?php endif;?></a>
        <div class="account-wishlist-copy"><small><?=htmlspecialchars((string)($p['brand_name']??store_t('Product')),ENT_QUOTES,'UTF-8')?></small><a href="<?=htmlspecialchars(store_product_url($p),ENT_QUOTES,'UTF-8')?>"><strong><?=htmlspecialchars((string)$p['name'],ENT_QUOTES,'UTF-8')?></strong></a><?php if(!empty($p['first_available_variant_label'])):?><span><?=htmlspecialchars((string)$p['first_available_variant_label'],ENT_QUOTES,'UTF-8')?></span><?php endif;?><div class="account-wishlist-price"><b><?=htmlspecialchars(store_money($p['price']??null,(string)($p['currency']??'EGP')),ENT_QUOTES,'UTF-8')?></b><?php if($sale):?><del><?=htmlspecialchars(store_money($regular,(string)($p['currency']??'EGP')),ENT_QUOTES,'UTF-8')?></del><?php endif;?></div><span class="account-stock-state <?=$stock>0?'is-in':'is-out'?>"><?=store_h(store_t($stock>0?'In stock':'Out of stock'))?></span></div>
        <div class="account-wishlist-actions"><a class="app-button primary" href="<?=htmlspecialchars(store_product_url($p),ENT_QUOTES,'UTF-8')?>"><?=store_h(store_t('VIEW PRODUCT'))?></a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="app-button secondary" type="submit" aria-label="<?=store_h(store_t('Remove'))?> <?=htmlspecialchars((string)$p['name'],ENT_QUOTES,'UTF-8')?> <?=store_h(store_t('from wishlist'))?>"><?=store_h(store_t('REMOVE'))?></button></form></div>
      </article>
    <?php endforeach;?>
  </div><?php endif;?>
</section>
<?php account_page_end('WISHLIST'); ?>
